Worked example:

```javascript
function publicNote(note) {
  return {id:note.id,title:note.title};
}
console.log(publicNote({"id":1,"title":"Moon","ownerEmail":"private@example.test"}));
```
The returned value is {"id":1,"title":"Moon"}.

after:
```javascript
function publicNote(note) {
  return {id:note.id,title:note.title};
}
console.log(publicNote({"id":1,"title":"Moon","ownerEmail":"private@example.test"}));
```
The result contains id: 1 and title: "Moon". The private ownerEmail field is not copied.
